window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d09_pre"]={"title": "Проект эксплуатации ГТС Ni отстойник, шифр 1006.3-ПрЭ", "pages": 10, "pagesTxt": ["[стр. 1]\nПРОЕКТ ЭКСПЛУАТАЦИИ ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЙ НИКЕЛЕВОГО ОТСТОЙНИКА \n(ОТСЕКИ «СЕВЕРНЫЙ», «ЮЖНЫЙ», «ВОСТОЧНЫЙ»)\nНОРИЛЬСКОЙ ОБОГАТИТЕЛЬНОЙ ФАБРИКИ на 2024-2025 гг.\n \nПРОЕКТ ЭКСПЛУАТАЦИИ \u000b \n  \n1006.3-ПрЭ", "[стр. 2]\nПРОЕКТ ЭКСПЛУАТАЦИИ ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЙ НИКЕЛЕВОГО ОТСТОЙНИКА \n(ОТСЕКИ «СЕВЕРНЫЙ», «ЮЖНЫЙ», «ВОСТОЧНЫЙ»)\nНОРИЛЬСКОЙ ОБОГАТИТЕЛЬНОЙ ФАБРИКИ на 2024-2025 гг.\n\nПРОЕКТ ЭКСПЛУАТАЦИИ \u000b \n\n1006.3-ПрЭ \n\nНе присвоен_________________ \nКод в Российском регистре ГТС", "[стр. 3]\n/\n\n\n\n\n\n\nУТВЕРЖДАЮ\n\u0007\n\u0007Заместитель Генерального директора ООО «Медвежий ручей» -\nглавный инженер\n\u0007\n\u0007\n\u0007\n\u0007\n\u0007Уваров И. И.\n\u0007\n\u0007\n\u0007\n\u0007\n\u00072023\n\u0007\n\u0007\n\n\nПРОЕКТ ЭКСПЛУАТАЦИИ ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЙ НИКЕЛЕВОГО ОТСТОЙНИКА\n(ОТСЕКИ «СЕВЕРНЫЙ», «ЮЖНЫЙ», «ВОСТОЧНЫЙ»)\nНОРИЛЬСКОЙ ОБОГАТИТЕЛЬНОЙ ФАБРИКИ\nна 2024-2025 гг.\n\n\n\nНе присвоен_________________\nКод в Российском регистре ГТС", "[стр. 4]\nСПИСОК ОТВЕТСТВЕННЫХ ИСПОЛНИТЕЛЕЙ\nГенеральный директор\n\u0007\n\u0007Вайкум Владимир Андреевич\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007идентификационный номер в национальном реестре специалистов РФ НОПРИЗ – П-038284\nАттестован комиссией Енисейского управления Ростехнадзора в области безопасности ГТС Протокол № 66-22-6713\n\u0007\n\u0007Технический директор\n\u0007\n\u0007Поваренкин Валерий Александрович\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007идентификационный номер в национальном реестре специалистов РФ НОПРИЗ – П-038388\nАттестован комиссией Енисейского управления Ростехнадзора в области безопасности ГТС Протокол № 66-22-7176; № 66-22-6701.\n\u0007\n\u0007\n\u0007\n\u0007\n\u0007\n\u0007ГИП\n\u0007\n\u0007Гренделис Виктория Владаса\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007идентификационный номер в национальном реестре специалистов РФ НОПРИЗ – П-078881\nАттестован комиссией Енисейского управления Ростехнадзора в области безопасности ГТС Протокол № 66-22-7188; № 66-22-6759\n\u0007\n\u0007Ведущий специалист гидротехник\n\u0007\n\u0007Иванова Татьяна Александровна\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007Аттестована комиссией Енисейского управления Ростехнадзора в области безопасности ГТС Протокол № 66-22-6753; № 66-22-7130\n\u0007\n\u0007Главный специалист\n\u0007\n\u0007Ягин Владимир Павлович\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007\n\u0007\n\u0007Главный специалист\n\u0007\n\u0007Чудинов Сергей Николаевич\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007Аттестован комиссией Енисейского управления Ростехнадзора в области безопасности ГТС Протокол № 66-22-8033\n\u0007\n\u0007Инженер 2 категории гидротехник\n\u0007\n\u0007Сачкова Наталия Дмитриевна\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007Аттестован комиссией Енисейского управления Ростехнадзора в области безопасности ГТС Протокол № 66-22-6754;\nПротокол № 66-22-7133\n\u0007\n\u0007Ведущий инженер\n\u0007\n\u0007Яковлева Ирина Ильинична\n\u0007\n\u0007\n\u0007«___» _____________ 2023 г.\n\u0007\n\u0007\n\u0007", "[стр. 5]\nСОДЕРЖАНИЕ\nВведение\t4\nПринятые сокращения\t5\n1\tКраткая пояснительная записка\t6\n1.1\tОсновные технологические параметры\t6\n1.1.1\tПроектные характеристики и класс сооружения\t6\n1.1.2\tОсновные технологические параметры работы никелевого отстойника (отсеки «Северный», «Южный», «Восточный») НОФ на планируемый период\t7\n1.1.3\tОбщая характеристика металлосодержащего продукта и осветлённой воды\t8\n1.2\tТехнологическая схема системы гидротранспорта сливов и металлосодержащих продуктов, оборотного водоснабжения\t8\n1.3\tТехнологическая схема системы складирования\t11\n1.3.1\tСистема складирования\t11\n1.3.2\tТехнология складирования в летний период\t14\n1.3.3\tТехнология складирования в зимний период\t14\n1.4\tРасчётные расходы дренажей\t17\n1.5\tХарактер деформаций откосов\t17\n2\tСостав и периодичность натурных наблюдений за состоянием сооружений\t18\n3\tКонтролируемые параметры сооружений, критерии безопасности\t20\n3.1\tТехнологические процессы\t20\n3.1.1\tГидротранспорт сливов и сгустителей НОФ\t20\n3.1.2\tГидротранспорт металлосодержащего продукта\t21\n3.1.3\tСкладирование концентрата в отстойник\t23\n3.1.4\tСистема оборотного водоснабжения\t23\n3.1.5\tКонтроль за работой систем гидротранспорта и оборотного водоснабжения\t25\n3.2\tКонтроль за безопасностью ГТС\t25\n3.2.1\tКонтроль системы КИА\t26\n3.2.2\tОграждающие дамбы отсеков «Северный», «Южный» «Восточный и их основания\t26\n3.2.3\tКонтроль состояния ёмкости отсеков отстойников\t28\n3.2.4\tКонтроль технического состояния гидротехнических сооружений\t29\n3.2.5\tТехника безопасности при эксплуатации и ремонте сооружений и оборудования\t30\n3.2.6\tПротивопожарные мероприятия\t30\n3.2.7\tМолниезащита сооружений\t31\n3.3\tВлияние отстойников на окружающую среду\t31\n4\tВедение наблюдений и контроль за безопасностью ГТС\t33\n4.1\tНаблюдения за уровенным режимом прудов отстойников и контролем за деформациями ограждающей дамбы\t33\n4.1.1\tОборудование для ведения мониторинга\t33\n4.1.2\tМесто расположения\t33\n4.2\tВедение контроля\t33\n4.3\tКонтролируемые параметры и критерии безопасности\t35\n5\tПеречень персонала, оборудования и механизмов, необходимых при эксплуатации отстойника никелевого концентрата Норильской обогатительной фабрики\t39\n6\tМероприятия по предупреждению чрезвычайных ситуаций\t42\n7\tМероприятия на случай консервации\t45\nПриложение А Техническое задание\t46\nГрафические приложения\t64", "[стр. 6]\nВВЕДЕНИЕ\nПроект эксплуатации гидротехнических сооружений никелевого отстойника (отсеки «Северный», «Южный», «Восточный») Норильской обогатительной фабрики на 2024-2025 гг. разработан специалистами ООО «Институт Красноярскгидропроект» по договору с ООО «Медвежий ручей» № МР-2450/2023 от 22.08.2023 г на «Работы по разработке разрешительной и эксплуатационной документации, инспекторскому надзору за техническим состоянием, оказанию инжиниринговых, аналитических и консультационных услуг по обеспечению безопасности и надёжности гидротехнических сооружений Норильской обогатительной фабрики ООО «Медвежий ручей».\nПроект эксплуатации выполнен в соответствии с требованиями законодательных актов и нормативных документов:\nФедерального закона № 384-ФЗ «Технический регламент о безопасности зданий и сооружений»;\nФедерального закона № 117-ФЗ «О безопасности гидротехнических сооружений»;\nФедерального закона № 7-ФЗ «Об охране окружающей среды»;\nФедерального закона № 89-ФЗ «Об отходах производства и потребления»;\nПБ 03-438-02 «Правила безопасности гидротехнических сооружений накопителей жидких промышленных отходов» (использованы справочно).\nЦель разработки проекта эксплуатации ГТС отстойника никелевого концентрата Норильской обогатительной фабрики является разработка всестороннего и комплексного документа, определяющего оптимальный порядок и режим работы, безопасную и эффективную эксплуатацию комплекса сооружений, входящих в состав ГТС НОФ, с учётом фактического их состояния.\nПРИНЯТЫЕ СОКРАЩЕНИЯ\nГТС – гидротехническое сооружение;\nМР – Медвежий ручей;\nНОФ – Норильская обогатительная фабрика;\nУСНК – участок складирования никелевого концентрата;\nГТЛ ЦНГТС – гидротехническая лаборатория центра по надзору за гидротехническими сооружениями;\nЦГТС и ГТ - цех гидротехнических сооружений и гидротранспорта НОФ;\nИТР – инженерно-технический работник;\nПЛА – план ликвидации аварии;\nНИР – научно-исследовательская работа;\nОООС – охрана и оздоровление окружающей среды;\nПлНС – плавучая насосная станция;\nКИА – контрольно-измерительная аппаратура;\nАСДК – автоматизированная система диагностического контроля;\nЛСО – локальная система оповещения;\nАСЦО – автоматизированная система централизованного оповещения;\nПДК – предельно допустимая концентрация;\nПУМ – прямой удар молнии.\nКРАТКАЯ ПОЯСНИТЕЛЬНАЯ ЗАПИСКА\nОсновные технологические параметры \nПроектные характеристики и класс сооружения\nОтстойник никелевого концентрата, состоящий из трёх отсеков: «Северный», «Южный» и «Восточный», расположен в акватории бывшего озера Школьное и в ложе двух небольших безымянных озёр. Ограждающие дамбы никелевого отстойника расположены к югу от жилой зоны Центрального района МО г. Норильск.\n/\nРисунок 1.1 – Схема расположения никелевого отстойника\nНикелевый отстойник выполнен по проекту института «Норильскпроект» и введён в эксплуатацию в 1974 году. К настоящему времени никелевый отстойник находится в эксплуатации 49 лет.\nНормативный срок эксплуатации для сооружений IV класса - 50 лет, согласно СП 58.13330.2019 «Гидротехнические сооружения. Основные положения».\nВ состав комплекса ГТС никелевого отстойника входят:\nограждающая дамба отсеков «Северный», «Южный» и «Восточный» Никелевого отстойника. Отсеки служат для приёма технологических стоков из НОФ и УСНК;\nсифонный водозабор для забора осветлённой воды из Северного отстойника во всасывающий коллектор насосной станции;\nбереговая насосная станция для возврата из ёмкости отсеков осветлённой оборотной воды в технологический процесс на Норильскую обогатительную фабрику и металлосодержащего продукта на УСНК;\nсистема трубопроводов (подводящих и отводящих).\nТакже в эксплуатации цеха гидромеханизации находится плавучая насосная станция (ПлНС). Для перекачки металлосодержащего продукта используется технологическое оборудование - земснаряды.\nОткосы ограждающей дамбы, верховой и низовой - 1:1,5.\nМаксимальная высота дамб – 10,00 м (Северный отсек).\nКласс ГТС по проекту – IV.\nКласс опасности ГТС (в соответствии с Постановлением Правительства РФ от 05.10.2020 № 1607 «Об утверждении критериев классификации гидротехнических сооружений») – не определялся.\nВ соответствии с Критериями классификации гидротехнических сооружений, утвержденными Постановлением Правительства РФ от 05.10.2020 № 1607, ГТС могут быть отнесены к IV классу по нижеследующим основаниям:\nклассы ГТС в зависимости от их высоты и типа грунта оснований, плотины из грунтовых материалов, сооружения (дамбы), предназначенные для использования водных ресурсов и предотвращения негативного воздействия вод – IV – максимальная строительная высота 6,14 м (северный отсек);\nклассы ГТС в зависимости от последствий возможных гидродинамических аварий – IV – при реализации аварии по сценарию А4 возможно будет нанесён вред только эксплуатационному персоналу в количестве 1 человека. Смертельных случаев не прогнозируется; объекты экономики, транспорта и связи, а также населённые пункты находятся вне зоны воздействия потока в результате аварий на ГТС.\nКласс опасности отходов – отходы не складируются, в отсеках никелевого отстойника происходит осаждение и накопление твёрдых частиц металлосодержащего продукта, направляемом на УСНК для дальнейшего получения никелевого концентрата.\nОсновные технологические параметры работы никелевого отстойника (отсеки «Северный», «Южный», «Восточный») НОФ на планируемый период\nНазначение никелевого отстойника – разделение сливов на металлосодержащий продукт и осветлённую воду. Осветлённая вода по водопропускным гильзам поступает в Северный отсек, откуда по сифонному водозабору подаётся в насосную станцию и далее водяными насосами перекачивается на НОФ в баки оборотной воды. Металлосодержащий продукт из отсеков земснарядами перекачивается на всасывающий коллектор песковых насосов береговой насосной станции и далее на УСНК.\nМаксимальный расход (технологические сливы НОФ), поступающий в отстойники, составляет 1143,65 м3/час.\nМаксимальная пропускная способность сифонного водозабора Северного отсека 3200,00 м3/час.\nИз Восточного отсека осветлённая вода поступает в Северный отсек по водопропускным гильзам из стальных труб DN600, DN800 (суммарным расходом 0,31 м3/с, 1143,65 м3/час).\nОбщая характеристика металлосодержащего продукта и осветлённой воды\nОбщая характеристика металлосодержащего продукта:\nсредневзвешенный размер частиц грунта - 0,2 мм;\nплотность частиц грунта - 2,5 т/м3;\nплотность сухого грунта - 0,9 т/м3.\nХимический состав осветлённой воды в отстойнике представлен в таблице Таблица 1.1.\nТаблица 1.1 - Химический состав осветлённой воды в отстойнике\nНаименование компонента\n\u0007Единицы\nизмерения\n\u0007Содержание\n\u0007\n\u0007рН\n\u0007ед. pн\n\u000711,01\n\u0007\n\u0007Плотность\n\u0007г/см3\n\u00071,000\n\u0007\n\u0007Щёлочность: свободная\n\u0007мг-экв/дм3\n\u00071,8\n\u0007\n\u0007общая\n\u0007мг-экв/дм3\n\u00072,2\n\u0007\n\u0007Сухой остаток\n\u0007г/дм3\n\u00073,70\n\u0007\n\u0007Остаток после прокаливания\n\u0007г/дм3\n\u00072,72\n\u0007\n\u0007Содержание ионов кальция\n\u0007г/дм3\n\u00070,67\n\u0007\n\u0007Содержание ионов магния\n\u0007мг/дм3\n\u0007<2,0\n\u0007\n\u0007Содержание хлорид–иона\n\u0007г/дм3\n\u00070,13\n\u0007\n\u0007Содержание тиосульфат–иона\n\u0007г/дм3\n\u00070,46\n\u0007\n\u0007Содержание сульфат–иона\n\u0007г/дм3\n\u00071,66\n\u0007\n\u0007Содержание бутилового ксантогената калия\n\u0007мг/дм3\n\u00072,82\n\u0007\n\u0007Содержание бутилового аэрофлота \n\u0007мг/дм3\n\u0007>10\n\u0007\n\u0007Содержание ДМДК\n\u0007мг/дм3\n\u00072,0\n\u0007\n\u0007Содержание вспенивателя (Т-92)\n\u0007мг/дм3\n\u00070,30\n\u0007\n\u0007Содержание взвешенных частиц\n\u0007г/дм3\n\u0007>1,2\n\u0007\n\u0007Содержание органических соединений (нефтепродукты)\n\u0007мг/дм3\n\u0007>30\n\u0007\n\u0007 Технологическая схема системы гидротранспорта сливов и металлосодержащих продуктов, оборотного водоснабжения\nТехнологические потоки на никелевый отстойник распределяются следующим образом:\nПоступление: \nВосточный отсек - сливы НОФ DN400, сливы УСНК DN1000.\nСеверный отсек – перелив осветлённой воды через водопропускные гильзы DN600, DN800 мм из Восточного отсека.\nЮжный отсек - сливы НОФ DN400.\nОтведение:\nВосточный отсек - перелив осветлённой воды через водопропускные гильзы DN600, DN800 мм в Северный отсек;\nСеверный отсек - осветлённая вода из пруда отсека по сифону DN800 в насосную станцию никелевого концентрата; откачка металлосодержащего продукта DN250 земснарядом «Ахтарец» и гидромонитором «Watermaster Classic IV» через зумпф в насосную станцию, а при необходимости в Южный отсек DN273;\nЮжный отсек - перекачка земснарядом 400/40 «Ахтарец» осветлённой воды из пруда в Северный отсек DN400, откачка металлосодержащего продукта земснарядом «SHARK» SH-4250-60-30D№1 через зумпф в насосную станцию никелевого концентрата DN400.\nПульпа металлосодержащего продукта из отсека земснарядом подается в зумпф, расположенный на ограждающей дамбе соответствующего отсека, откуда самотёком поступает в насосную станцию во всасывающий коллектор грунтовых насосов.\nЗумпф оборудован сороудерживающей решёткой для исключения попадания каких-либо крупных включений в песковые насосы.\nПроектные сроки складирования – проектом не определены. Ёмкости отстойника никелевого концентрата являются буферными и обеспечивают необходимый объём складирования с учётом перекачки металлосодержащего продукта из отсеков земснарядами и отвода осветлённой воды из отстойника.\nНеобходимость разработки накопившегося металлосодержащего продукта в конкретном отстойнике определяется графиком ведения работ, составляемым эксплуатацией в зависимости от объёма заполнения данного отсека.\nСифонный водозабор\nСифонный водозабор предназначен для забора осветлённой воды из Северного отсека в береговую насосную станцию никелевого концентрата. Максимальная пропускная способность сифонного водозабора составляет 3200 м3/час.\nШирина в свету входного отверстия сифона – 0,8 м.\nПроектная отметка забральной кромки капора сифона – 109,6 м.\nПроектная отметка верха гребня водослива – 109,0 м.\nБереговая насосная станция никелевого концентрата\nВ насосную станцию поступает:\nосветлённая вода (через сифон) во всасывающий коллектор водяных насосов;\nпульпа металлосодержащего продукта во всасывающий коллектор песковых насосов из зумпфа Северного отстойника.\nВ насосной станции никелевого отстойника установлено следующее насосное оборудование:\nцентробежные водяные насосы ЦН1000-180 в количестве 5 насосных агрегатов, работающих параллельно. Из них 2 рабочих насоса, 3 в резерве и ремонте.\nпесковые насосы 8ПС-8 (6 шт.). Из имеющихся шести песковых насосов образованы три спарки, из которых одна рабочая, две в резерве.\nвакуумный насос ВВН-25 в количестве 1 насосных агрегатов.\nОсветлённая вода подаётся водяными насосами в водооборот НОФ.\nПульпа металлосодержащего продукта песковыми насосами подаётся на УСНК. \nВакуумные насосы используются для зарядки сифона.\nНасосная станция оборудована электрифицированной запорной трубопроводной арматурой.\nЗемснаряды\nВ настоящее время в эксплуатации цеха гидромеханизации находится три плавучие несамоходные насосные установки:\nв Северном отсеке разработку металлосодержащего продукта ведёт дизель электрический земснаряд «Ахтарец» производительностью 400 м3/час, при необходимости применяют гидромонитор «Watermaster Classic IV» или земснаряд «SHARK» SH-4250-60-30D№1 производительностью 500 м3/час и 1000 м3/час соответственно.\nСистема трубопроводов (подводящих и отводящих)\nПодводящие трубопроводы:\nСеверный отсек – перелив осветлённой воды через водопропускные гильзы DN600, DN800 мм из Восточного отсека, перелив осветлённой воды через водопропускную гильзу DN800 мм из Южного отсека (не эксплуатируется).\nВосточный отсек - сливы НОФ DN400, длина – 1 500,0 м; сливы УСНК DN1000 1400 м.п. Материал – металлические.\nОтводящие трубопроводы:\nВосточный отсек - перелив осветлённой воды через водопропускные гильзы в Северный отсек;\nСеверный отсек - осветлённая вода из пруда отсека по сифону, DN800 в насосную станцию никелевого концентрата; откачка металлосодержащего продукта DN250 земснарядом «Ахтарец» через зумпф в насосную станцию, далее на УСНК.\nОсветлённая вода подается водяными насосами в водооборот НОФ 2DN720 мм. Длина водовода – 1 862,0 м. Материал – металлические.\nПульпа металлосодержащего продукта песковыми насосами подаётся от насосной станции на УСНК DN273 мм, длина – 1 500,0 м.\nМатериал – металлические.\nТип дренажа\nДренажные сооружения по контуру никелевого отсека не предусмотрены.\n/\nРисунок 1.2 - Технологическая схема отстойника никелевого концентрата\nТехнологическая схема системы складирования \nСистема складирования \nОтстойник никелевого концентрата, состоящий из трёх отсеков: «Северный», «Южный» и «Восточный».\nЁмкость Южного и Восточного отсеков организована путём сооружения котлована с последующей отсыпкой ограждающей дамбы по всему периметру грунтом выемки из котлована. Ёмкость Северного отсека организована углублением дна оз. Школьное, в ложе которого он расположен. Ограждающая дамба также выполнена по всему контуру отсека.\nТехнические характеристики отстойников показаны в таблице Таблица 1.2. \nГрафики площадей и объёмов, уточнённые для ёмкости отсеков, спрофилированной до проектной отметки дна с уклоном подводных откосов 1:2,5 представлены на рисунках (Рисунок 1.3, Рисунок 1.4, Рисунок 1.5). При выемке концентрата из отсеков кривые площадей и объёмом подлежат уточнению на основании промеров глубин.\nТаблица 1.2 – Технические характеристики отстойников \n№ п/п\n\u0007Наименование показателя\n\u0007Северный\n\u0007Южный\n\u0007Восточный\n\u0007\n\u00071\n\u00072\n\u00073\n\u00074\n\u00075\n\u0007\n\u00071\n\u0007Проектная отметка гребня ограждающей дамбы, м \n\u0007110,0\n\u0007109,0\n\u0007112,0\n\u0007\n\u00072\n\u0007Проектный уровень воды в прудах, м \n\u0007109\n\u0007108\n\u0007111\n\u0007\n\u00073\n\u0007Проектная отметка дна котлованов, м\n\u0007100,0\n\u0007100,0\n\u0007101,5\n\u0007\n\u00074\n\u0007Максимальная мощность загрузки концентрата, м\n\u00079,0\n\u00078,0\n\u00079,5\n\u0007\n\u00075\n\u0007Площадь отсеков (по внутренней кромке гребня дамбы), тыс. м2\n\u000719,81 \n\u000723,40\n\u000710,56 \n\u0007\n\u00076\n\u0007Объём отсеков по данным декларации безопасности ГТС 2003 г, тыс. м3\n\u000760,925\n\u000788,483\n\u000723,480\n\u0007\n\u00077\n\u0007Уточненный объём отсеков (при подводных откосах 1:2,5)\n\u0007119,173\n\u0007158,584\n\u000757,092\n\u0007\n\u0007\n/\nРисунок 1.3 – Кривые площадей и объёмов Северного отсека\n/\nРисунок 1.4 – Кривые площадей и объёмов Южного отсека\n/\nРисунок 1.5 – Кривые площадей и объёмов Восточного отсека\nТехнология складирования в летний период\nТехнология подачи сливов в летний период заключается в обеспечении равномерного слива в отсеки отстойника в течение всего времени подачи сливов. Для обеспечения максимального осветления воды сброс сливов и забор осветлённой воды следует производить с противоположных сторон отсека.\nКонтроль за уровнем воды в отсеках осуществляется при помощи водомерных реек, установленных в отсеках отстойника. Замеры выполняются вручную, 2 раза в сутки. Результаты замеров фиксируются в журнале \nКонтроль состояния трубопроводов (в границах обслуживания) осуществляет обслуживающий персонал ЦГТС и ГТ, производящий визуальный осмотр трубопроводов по графику, утверждённому начальником цеха, но не реже 1 раза в сутки.\nПодготовка к пропуску паводковых вод начинают с обеспечения определённого запаса в отстойниках для безаварийного приёма воды. При наступлении положительных температур устанавливают ежесуточный контроль за прохождением паводковых вод. После пропуска паводковых вод все сооружения подлежат осмотру, выявленные повреждения устраняются.\nРезультаты обходов трубопроводов регистрируют в журнал обходов ЦГТС и ГТ. Регистрацию в журнале производит мастер ЦГТС и ГТ.\nЗапрещено производить осмотры путём передвижения по трубам, для этой цели в летнее время использовать инспекторскую дорогу вдоль трубопровода. При осмотрах обращать внимание на просадку грунта, образование луж, свищей на трубах по трассе, которые свидетельствуют о порыве трубопроводов.\nТехнология складирования в зимний период\nВ зимний период с температурой воздуха ниже минус 5 ºС при образовании ледяного покрова на поверхности отстойника для нормальной эксплуатации плавучих насосных установок следует следить за наличием майны в районе забора воды. Слив производить под лёд. \nПеред зимним складированием необходимо:\nсоставить и утвердить план и график работ по зимнему складированию металлосодержащего продукта;\nнакопить объём воды, достаточный для зимней укладки металлосодержащего продукта под воду и оборотного водоснабжения предприятия с учётом потерь воды на льдообразование;\nнарастить выпуск трубопровода сливов до отстойного пруда;\nподготовить помещение для обогрева рабочих;\nпроверить работоспособность систем гидротранспорта сливов, металлосодержащих продуктов и оборотного водоснабжения.\nПри работе отстойника в случае выхода пульпы на лёд следует нарастить выпуск трубопровода сливов до следующей лунки.\nВ конце зимы, когда складирование под воду из проложенного по льду выпуска невозможен, слив следует производить выпуском из торца трубопровода слива у уреза воды отстойника.\nПри подготовке земснаряда в зимний период необходимо:\nзаменить смазку всех узлов на зимнюю;\nутеплить машинный зал и палубные надстройки земснаряда, обеспечить обогрев вспомогательных насосов и трубопроводов, установить в машинном зале термометры;\nсоздать и поддерживать майну вокруг земснаряда и плавучего пульпопровода;\nследить за состоянием понтонов плавучего пульпопровода;\nсодержать выпуски для опорожнения плавучих пульпопроводов в рабочем состоянии;\nлюки верхней палубы понтона должны иметь водозащитные борта;\nсодержать в чистоте палубу, трапы, мостики, переходы и лестницы земснаряда. Снег и лёд с палубы следует систематически убирать;\nзапрещается эксплуатация земснаряда с открытыми люками, трещинами в понтоне;\nна видных местах в земснаряде должны быть расположены спасательные принадлежности (круги, спасательные жилеты);\nземснаряд должен иметь устойчивую радиосвязь с береговым оператором (диспетчером);\nна земснаряде должны находиться в рабочем состоянии противопожарное оборудование, инструменты. Перечень противопожарного оборудования необходимо согласовать с органами пожарного надзора.\nМинимальные площади майны, которые необходимо поддерживать для осуществления технологических перемещений земснаряда, приведены в таблице Таблица 1.3.\nТаблица 1.3 – Минимальные площади майны для земснаряда\nПроизводительность земснаряда, м3/ч\n\u00071000-1200\n\u00071600-2400\n\u00072400-3600\n\u00074000\n\u00075000\n\u000710 000\n\u0007\n\u0007Площадь майны, м2\n\u0007600-800\n\u00071000-1200\n\u00071400-1600\n\u00071800-2000\n\u00072500-3000\n\u00073500-4000\n\u0007\n\u0007По условиям техники безопасности и обеспечения проектной производительности земснарядов уменьшение площади майны по сравнению с указанной в таблице Таблица 1.3 допускается не более чем на 20 % и только на непродолжительное время при резком ухудшении погоды. Увеличение размеров майны, по сравнению с указанными, нецелесообразно из-за увеличения непроизводительных затрат энергии и потерь естественных запасов тепла расчищаемой ёмкости.\nВ зимний период проход по льду отстойников без предварительного опробования запрещается. Проход по льду толщиной менее 10 см запрещён.\nДо работы или переправы по льду должны быть произведены измерения толщины льда. Расстояние между соседними лунками в намеченных створах следует принимать в пределах 10 м. Промерочные лунки на местах следует обозначать вехами.\nПередвижение персонала и организация переправ по льду может производиться при толщине льда, указанной в таблице Таблица 1.4, по наряду-допуску в присутствии ответственного руководителя.\nТаблица 1.4 – Минимальная толщина льда при передвижению по льду\nВид нагрузки \n\u0007Масса нагрузки, т\n\u0007Толщина ледяного покрова, безопасная при температуре воздуха от -1 до -20 °С, см\n\u0007Минимальное расстояние между транспортом, м\n\u0007\n\u0007Человек со снаряжением\n\u00070,1\n\u000710\n\u00075\n\u0007\n\u0007Автомашина грузоподъемностью 1,5 т с грузом\n\u00073,5\n\u000725\n\u000720\n\u0007\n\u0007Автомашина с грузом\n\u00076,5\n\u000735\n\u000725\n\u0007\n\u0007Автосамосвал с грузом или бульдозер\n\u00078,5\n\u000740\n\u000725\n\u0007\n\u0007Автотягач с грузом или трактор\n\u000710\n\u000740\n\u000730\n\u0007\n\u0007Гусеничный кран с грузом\n\u000720\n\u000760\n\u0007-\n\u0007\n\u0007Примечания:\nУказанные значения толщины льда относятся к воде с минерализацией до 1000 мг/л.\nЗначение допускаемой толщины льда следует увеличить:\nВ 1,1 раза – при средней температуре воздуха в последние трое суток -5 °С;\nВ 1,4 раза – при температуре 0 °С;\nВ 1,5 раза – при температуре выше 0 °С.\nПрочность льда весной принимается в два раза меньше. При расчете принимается только толщина прочных слоев льда. Слои снежного и пористого, пропитанного водой льда в расчет не принимаются.\n\u0007\n\u0007Для обеспечения сохранности КИА при очистке территории отстойников от снега на зимний период к надземной части КИА должны прикрепляться предупредительные шесты, окрашенные «под зебру» или в яркий цвет, хорошо различимый на фоне снега.\nКонтроль состояния трубопроводов (в границах обслуживания) осуществляет обслуживающий персонал ЦГТС и ГТ, производящий визуальный осмотр трубопроводов по графику, утверждённому начальником цеха, но не реже 1 раза в сутки.\nРезультаты обходов трубопроводов регистрируют в журнал обходов ЦГТС и ГТ. Регистрацию в журнале производит мастер ЦГТС и ГТ.\nЗапрещено производить осмотры путём передвижения по трубам, для этой цели в зимний период использовать вездеходный транспорт. При осмотрах обращать внимание на просадку грунта, появление наледей по трассе, которые свидетельствуют о порыве трубопроводов.\nДля предупреждения замораживания трубопроводов в зимний период ведут постоянный контроль за их состоянием. Ежегодно с целью подготовки систем гидротранспорта и оборотного водоснабжения к безопасной эксплуатации в зимний период следует проводить мероприятия, предупреждающие размораживание трубопроводов в зимний период, выполняемые не позднее 3-го квартала текущего года:\nвыполнить работы по восстановлению теплоизоляции на повреждённых участках трубопроводов;\nпроизвести ревизию, при необходимости ремонт либо замену дренажной арматуры, установить указатели высотой не менее 2 м с соответствующей надписью в местах нахождения дренажей по трассе трубопроводов;\nустановить на участках пересечения трубопроводов с автодорогами, на участках примыкания трубопроводов к проезжей части автодорог ближе 3 м указатели высотой не менее 2 м с соответствующей надписью.\nЛюбую остановку трубопроводов и проведение плановых или профилактических работ выполняют по утверждённым графикам с обязательным уведомлением сменного матера, начальника ЦГТС и ГТ, диспетчера НОФ.\nВ зимнее время обязательно контролировать температуру сливов на выходе из фабрики.\nКонтроль за уровнем воды в отстойниках в зимний период аналогичен летнему периоду.\nРасчётные расходы дренажей\nВ составе сооружений нет дренажей, поэтому требования не предъявляются.\nХарактер деформаций откосов\nНаиболее вероятными деформациями откосов при эксплуатации отстойника являются потеря устойчивости низового и верхового откосов ограждающей дамбы.\nКрутизна низового откоса ограждающей дамбы отстойника и надводной части верхового откоса ограждающей дамбы составляет 1:1,5. Крутизну бортов котлованов в отсеках отстойника при выемке металлосодержащих продуктов следует принять не круче 1:2,5.\nПри указанных заложениях устойчивость откосов обеспечивается, признаков потери устойчивости откосов при эксплуатации отстойника не выявлено. \nДля исключения потери устойчивости откосов опорожнение и наполнение отсеков отстойника водой следует производить такими темпами, которые не вызывают переувлажнения грунтов, слагающих ограждающую дамбу. \nМаксимальная скорость опорожнения и наполнения отсеков отстойника водой не должна превышать 0,5 м/сут.\nВыемку металлосодержащих продуктов при эксплуатации отстойника следует производить при постоянном контроле глубины забоя земснаряда, без перекопов ниже проектного дна и бортов. \nПри необходимости подъёма металлосодержащих продуктов ниже проектных отметок дна и бортов, выемку с перекопом следует производить по отдельному проекту с заменой металлосодержащих продуктов на минеральный грунт.\nСОСТАВ И ПЕРИОДИЧНОСТЬ НАТУРНЫХ НАБЛЮДЕНИЙ ЗА СОСТОЯНИЕМ СООРУЖЕНИЙ\nПо данным Декларации безопасности ГТС 2023 г. и проекта мониторинга (шифр 07-04-231, 2023 г.), состав и периодичность визуальных и инструментальных наблюдений, а также ответственные подразделения по контролю их технического состояния, приняты следующие:\nнаблюдения за геометрическими параметрами ограждающих дамб - 2 раза в год (ЦГТС и ГТ НОФ);\nнаблюдения за допустимым превышением отметки гребня дамб над уровнем воды в отстойных прудах - ежедневно (ЦГТС и ГТ НОФ);\nизмерение расходов профильтровавшейся воды в нижнем бьефе – в течение года (ЦНГТС);\nвизуальные наблюдения за состоянием ГТС – постоянно (ЦГТС и ГТ НОФ);\nконтроль и наблюдения за работой систем гидротранспорта, оборотного водоснабжения – ежедневно (ЦГТС и ГТ НОФ);\nконтроль износа стенок пульповодов и водоводов (за исключением новых участков трубопроводов на срок их гарантии от предприятия-изготовителя):\nизмерение толщины стенок металлических трубопроводов – 1 раз в год (ЦГТС и ГТ НОФ);\nсостояние металла трубопроводов; компенсаторов; запорной арматуры; состояние территории около трубопроводов; состояние трассы и материала трубопроводов; состояние эстакад, опор, мостиков - ежедневно (ЦГТС и ГТ НОФ);\nконтроль положения трассы трубопроводов - 1 раз в 5 лет (ЦГТС и ГТ НОФ);\nнаблюдения за параметрами пульпы – 1 раз в квартал (ЦГТС и ГТ НОФ, Технический отдел НОФ);\nнаблюдения за системой складирования и разработки металлосодержащего продукта - ежедневно (ЦГТС и ГТ НОФ);\nнаблюдения за сифонным водозабором – ежедневно (ЦГТС и ГТ НОФ);\nнаблюдения за береговой насосной станцией - не реже 1 раза в 1 час в периоды её использования (ЦГТС и ГТ НОФ);\nнаблюдение за состоянием технологического оборудования (земснаряды) - не реже 1 раза в час в периоды его использования (ЦГТС и ГТ НОФ);\nнаблюдение за качеством осветлённой воды (взвесь) - 2 раза в год (ЦГТС и ГТ НОФ, Отдел охраны окружающей среды);\nнаблюдения за состоянием контрольно-измерительной аппаратуры:\nпроверка устойчивости опорных реперов геодезической сети – не реже 1 раза в 3 года (ЦГТС и ГТ НОФ);\nгеодезические измерения планового и высотного положения КИА – 1 раз в год (ЦГТС и ГТ НОФ);\nкорректировка водомерной рейки – не менее 1 раза в год (ЦНГТС);\nпрогноз интенсивности и времени прохождения паводков – в течение года;\nпромеры глубин прудков-отстойников – 2 раза в год (ЦГТС и ГТ НОФ, ЦНГТС).\nТопографо-геодезические работы – продольные профили гребня ограждающих дамб, поперечные профили ограждающих сооружений, наблюдения за деформациями по поверхностным маркам (ЦНГТС).\nРежимные наблюдения с отбором проб из поверхностных источников – 2 раза в год (ЦГТС и ГТ НОФ, ОООС, КАУ).\nВыполнением квартальных обследований технического состояния ГТС никелевого отстойника занимается Центр по надзору за гидротехническими сооружениями ЗФ ПАО «ГМК «Норильский никель», ООО «Норникель. Технические сервисы» на основании договоров возмездного оказания услуг. По завершению обследований составляется отчётная документация, которая предоставляются Заказчику.\nКроме того, ГТЛ ЦНГТС выполняет следующие работы:\nкомплексные обследования ГТС;\nорганизация и контроль инженерных изысканий;\nоценка технического состояния ГТС.\nПри необходимости проведения НИР и разработки соответствующих рекомендаций по обеспечению безопасной эксплуатации ГТС, по согласованию с генпроектировщиком привлекаются организации, имеющие соответствующий опыт.\nНаблюдения за фильтрационным режимом включает в себя определение величины фильтрационных расходов на низовом откосе и химического состава фильтрующихся вод.\nКомиссионные обследования никелевого отстойника проводят два раза в год – перед и после паводка с включением в комиссии представителей ЦНГТС.\nПо результатам обследования составляется акт о готовности гидротехнических сооружений к пропуску паводковых вод и работе в зимних условиях перед наступлением зимнего периода.\nКОНТРОЛИРУЕМЫЕ ПАРАМЕТРЫ СООРУЖЕНИЙ, КРИТЕРИИ БЕЗОПАСНОСТИ\nКонтроль параметров должен вестись по следующим направлениям:\n1. Технологические процессы;\n2. Состояние гидротехнических сооружений;\n3. Влияние Никелевого отстойника на окружающую среду;\n4. Документация по ГТС;\n5. Состояние эксплуатационной службы, а также привлекаемых к эксплуатации других специализированных служб и организаций.\nС учётом фактического состояния сооружений отстойника предусматривается следующий состав натурных наблюдений и контроля.\nТехнологические процессы\nГидротранспорт сливов и сгустителей НОФ\nВ систему гидротранспорта входят:\nЮжный, Восточный отсек - сливы сгустителей НОФ DN400;\nВосточный отсек- сливы сгустителей УСНК DN1000.\nКонтроль процесса гидротранспорта включает технологический контроль пропускной способности трубопроводов и контроль характеристик и расходов транспортируемого в отсеки никелевого отстойника металлосодержащего продукта.\nТехнологический контроль системы гидротранспорта сливов должен также включать контроль степени износа стенок трубопроводов по трассе.\nЭксплуатационное состояние этих трубопроводов, а также количественный и качественный состав сбрасываемых сливов должны постоянно контролироваться службой эксплуатации.\nОсновными контролируемыми параметрами пульпы являются:\nрасход;\nконсистенция пульпы;\nгранулометрический состав и плотность частиц шламов ((s).\nНаблюдения за расходом пульпы выполняются ежесменно. Отбор проб пульпы производится 1 раз в квартал из выпуска для определения консистенции пульпы и гранулометрического состава. \nКонтролируемые параметры пульпы должны быть занесены в «Журнал контроля характеристик пульпы». \nПараметры пульпы должны соответствовать проектным значениям.\nКонтроль толщины стенок пульповодов выполняется 1 раз в год и производится акустическими толщиномерами, степень заиления устанавливается при ежегодной ревизии пульповодов. По мере износа их необходимо поворачивать на 120 ºC. Так же, 1 раз в год выполняются визуальные осмотры трубопроводов с полиуретановым покрытием, результаты осмотра отражаются в акте осмотра.\nВ соответствии с графиком осмотров трубопроводов, ежеквартально проводится ревизия трубопроводной арматуры. Результаты ревизии отражаются в «Журнале ревизии запорной арматуры» с подписью ответственных лиц.\nКонтроль проектного положения трассы трубопроводов выполняется 1 раз в 5 лет.\nЕжедневно контролируют состояние: металла трубопроводов, территории около трубопроводов, трассы и материала трубопроводов.\nКоличественным показателем состояния пульповодов является минимально допустимая толщина износа стенок труб. \nКачественными показателями, контролируемыми визуально на сооружениях гидротранспорта, являются:\nсостояние пульповодов;\nотсутствие течей, просадок опор, состояние футеровки и т. д.\nГидротранспорт металлосодержащего продукта\nКонтроль процесса гидротранспорта включает технологический контроль пропускной способности системы и контроль характеристик и расходов транспортируемого металлосодержащего продукта.\nВ систему гидротранспорта входят:\nбереговая насосная станция никелевого концентрата;\nкомплекс оборудования и механизмов для разработки и подъёма никелевого концентрата (земснаряды типа «Ахтарец», гидромонитор типа «Watermaster Classic IV», плавучий пульпопровод);\nзумпфы;\nтрубопроводы гидротранспорта DN250, DN273, DN350, DN500;\nСхема работы гидротранспорта приведена в Графических приложениях.\nОсновными контролируемыми параметрами пульпы являются:\nрасход;\nконсистенция пульпы;\nгранулометрический состав и плотность частиц шламов ((s).\nНаблюдения за расходом пульпы выполняются ежесменно. Отбор проб пульпы производится 1 раз в квартал отбор проб металлосодержащего продукта производится из зумпфов, перед насосной никелевого концентрата. \nКонтролируемые параметры пульпы должны быть занесены в «Журнал контроля характеристик пульпы». \nПараметры пульпы должны соответствовать проектным значениям.\nОсновными контролируемыми параметрами насосных агрегатов являются:\nрасход (производительность) насосов (м3/ч);\nдопустимый манометрический напор, развиваемый насосом;\nстепень износа рабочих органов – не более 20 %.\nКоличественными показателями работы насосов является:\nобъёмная производительность (Q), м3/ч;\nдавление (P), кг/см2;\nнагрузка (I), А.\nКонтролируемые параметры насосных агрегатов должны быть занесены в соответствующий журнал.\nПараметры насосных агрегатов должны соответствовать паспортным данным агрегатов.\n Качественными показателями системы гидротранспорта, контролируемыми визуально, являются:\nсостояние земснарядов и правильная их эксплуатация;\nсостояние плавучих трубопроводов – отсутствие течей в стыках трубопроводов, исправность понтонов;\nсостояние грунтовых насосов и приёмных зумпфов отстойника;\nсостояние напорных трубопроводов – отсутствие порывов и течей;\nсостояние насосного оборудования и арматуры – техническая исправность.\nВизуальные наблюдения за показателями работы земснарядов, проверка состояния оборудования выполняется не реже 1 раза в час в периоды его использования.\nКонтрольными параметрами пульповодов являются:\nманометрический напор в зависимости от расхода пульпы;\nсостояние и степень износа стенок пульповода;\nосадка опор и деформация трубопроводов.\nДля определения фактических потерь напора измеряется манометрический напор в конце трассы (на последнем доступном пульповыпуске). \nКонтроль толщины стенок пульповодов выполняется 1 раз в год и производится акустическими толщиномерами, степень заиления устанавливается при ежегодной ревизии пульповодов. По мере износа их необходимо поворачивать на 120 ºC. Так же, 1 раз в год выполняются визуальные осмотры трубопроводов с полиуретановым покрытием, результаты осмотра отражаются в акте осмотра.\nКонтроль проектного положения трассы трубопроводов выполняется 1 раз в 5 лет.\nЕжедневно контролируют состояние: металла трубопроводов, территории около трубопроводов, трассы и материала трубопроводов.\nВ соответствии с графиком осмотров трубопроводов ежеквартально проводится ревизия трубопроводной арматуры. Результаты ревизии отражаются в «Журнале ревизии запорной арматуры» с подписью ответственных лиц.\nКоличественным показателем состояния пульповодов является минимально допустимая толщина износа стенок труб. \nКачественным диагностическим показателем всей системы гидротранспорта хвостов является безаварийность её работы в течение года.\nСкладирование концентрата в отстойник\nНеобходимость разработки накопившегося металлосодержащего продукта в конкретном отсеке отстойника определяется графиком ведения работ, составляемым эксплуатацией в зависимости от объёма заполнения данного отсека.\nЁмкости отстойника никелевого концентрата являются буферными и обеспечивают необходимый объём складирования с учётом перекачки металлосодержащего продукта из отсеков земснарядами и отвода осветлённой воды из отстойника.\nКонтроль слива в отстойник состоит из ежедневных наблюдений за технологией слива концентрата и включает контроль следующих параметров:\nотметок горизонта воды – контроль ведётся по водомерной реке; \nперепада между гребнем ограждающего сооружения и горизонтом воды в отстойнике – вычисляется математически как разность отметок гребня ограждающего сооружения (верхней бровки откоса отстойника) и отметкой уровня воды. Перепад между гребнем ограждающего сооружения и горизонтом воды должен быть не менее 1,0 м.\nТехнология зимнего и летнего слива должна полностью соответствовать утверждённым проектам, разрабатываемым службой геотехконтроля.\nПо данным геодезических съёмок вычерчиваются:\nплан отстойника с расположением пульповодов, указанием их диаметров и расположения выпусков, КИА и закреплённых поперечников со створными знаками;\nпоперечные профили сооружения с нанесением уреза воды.\nПо результатам геодезических съёмок и промеров глубин определяются ежегодные объёмы налитого в отсеки концентрата и объём отсеков, крутизна откосов, вертикальные и горизонтальные смещения верхней бровки береговых склонов отстойника. Результаты расчётов отражаются в отчётах по геодезическим наблюдениям.\nСистема оборотного водоснабжения\nВ систему оборотного водоснабжения входят:\nбереговая насосная станция никелевого концентрата;\nсифонный водозабор DN 800;\nперепускные устройства № 1-№ 5 DN 800, DN 600;\nплавучая насосная станция типа «Ахтарец»;\nводоводы 2 DN 700, DN 400.\nКонтроль технологических процессов оборота осветлённой воды на отстойнике состоит:\nв определении объёмов оборотной воды, подаваемой из береговой насосной станции в баки оборотной воды НОФ;\nв определении объёмов оборотной воды, находящейся в отсеке отстойника и подаваемой из отсека в насосную станцию.\nКонтроль технологических процессов осветления и оборота технической воды в отсеках никелевого отстойника включает:\nконтроль уровня воды. Замеры выполняются по водомерной рейке, расположенной в каждом отсеке. Результаты замеров заносятся в «Журнал наблюдений за уровнями воды»;\nопределение степени механического осветления оборотной воды (по пробам, которые отбираются у сифонного водозабора насосной станции). Результаты замеров заносятся в «Журнал общего учёта химического анализа воды». Определяется качество воды по содержанию взвесей. Контроль производится по мере необходимости, но не менее 2-х раз в год.\nдля водоводов при наземной прокладке – контроль времени остановки при низких температурах и состояния зимнего утепления; контроль осадок опор и деформаций трубопроводов, герметичности стыков, швов, фланцевых соединений, состояния и работы трубопроводной арматуры, устройств защиты против гидроудара;\nдля водоводов при подземной прокладке – контроль за просадкой грунта по трассе трубопровода и поблизости от неё; появлением воды в непосредственной близости от трассы; образованием в зимнее время наледей по трассе или в непосредственной близости к ней;\nдля насосных агрегатов – контроль времени работы в межремонтный период, срока износа деталей;\nдля плавучей насосной станции – контроль герметичности стыков, состояния понтонов, водоприёмников и шарнирных соединений.\nОсновными диагностическими количественными показателями для оценки состояния системы оборотного водоснабжения являются:\nконтрольные показания приборов на насосных станциях;\nрасход оборотной воды (Q), м3/ч;\nдавление на напорной линии (P), кг/см2;\nнагрузка агрегата (I), А;\nкритическая температура воды в зимнее время в трубопроводе;\nминимальная глубина у водозабора – 2,0 м.\nКачественные контрольные показатели, контролируемые визуально на сооружениях системы оборотного водоснабжения, следующие:\nнаблюдения за исправностью и правильной эксплуатацией сифонного водозабора. Контроль осуществляется ежедневно.\nсостояние плавучей и береговой насосных станций – исправность насосных агрегатов и трубопроводов, трубопроводной арматуры, проверка показателей работы. Контроль осуществляется не реже 1 раза в 1 час в период её использования;\nсостояние водоводов – отсутствие течей, деформаций, исправность теплоизоляции.\nКачественным диагностическим показателем является готовность всей системы к безаварийной работе.\nКонтроль проектного положения трассы трубопроводов выполняется 1 раз в 5 лет.\nЕжедневно контролируют состояние: металла трубопроводов, территории около трубопроводов, трассы и материала трубопроводов.\nКонтроль насосного оборудования и трубопроводной арматуры насосных станций производится постоянно в процессе эксплуатации, в соответствии с местной инструкцией по эксплуатации и типовыми инструкциями на технологическое оборудование. Визуально контролируется целостность зданий насосных станций. Ревизия водоводов производится в соответствии с графиком осмотра трубопроводов гидротранспорта.\nКонтроль за работой систем гидротранспорта и оборотного водоснабжения\nДля контроля за работой гидротранспорта и оборотного водоснабжения должны быть установлены вакуумметры, манометры, расходомеры, плотномеры, уровнемеры, указатели уровня воды (мерные рейки) в отсеках отстойника.\nКонтроль за безопасностью ГТС\nГТС отстойника должны находиться под постоянным эксплуатационным контролем, что предусмотрено Федеральным законом № 117-ФЗ и СП 58.13330.2019, РД 03-259-98.\nЭксплуатация ГТС Никелевого отстойника осуществляется работниками ЦГТС и ГТ НОФ совместно с гидротехнической лабораторией ЦНГТС ЗФ ПАО «ГМК «Норильский никель».\nДля объекта в 2023 г разработаны «Правила эксплуатации ГТС Никелевого отстойника (отсеки «Северный», «Южный», «Восточный») Норильской обогатительной фабрики».\nНа Никелевом отстойнике (отсеки «Северный», «Южный», «Восточный») проводятся регулярные инструментальные и визуальные наблюдения за техническим состоянием ГТС.\nРезультаты наблюдений отражаются в журналах, где приводятся данные об имевших место нарушениях в техническом состоянии сооружений; характер нарушения; сведения о принятых мерах по устранению выявленных недостатков.\nДля проведения инструментальных наблюдений на ГТС Никелевого отстойника установлены водомерные рейки на каждом отсеке. Высотное положение рейки ежегодно корректируется при помощи геодезического оборудования, которое проходит все необходимые процедуры поверки, установленные законодательством.\nСостав КИА на Никелевом отстойнике представлен в таблице Таблица 3.1.\nТаблица 3.1 - Состав контрольно-измерительной аппаратуры на Никелевом отстойнике\nОбъект, на котором установлена КИА\n\u0007Тип КИА\n\u0007Количество установленной КИА, шт\n\u0007В исправном состоянии, шт\n\u0007Периодичность наблюдений\n\u0007\n\u0007Ограждающая дамба\n\u0007Поверхностные марки\n\u00075\n\u00075\n\u00072 раза в год\n\u0007\n\u0007\n\u0007Водомерные рейки\n\u00074\n\u00074\n\u0007ежедневно\n\u0007\n\u0007Другая КИА на ГТС отсутствует и не предусмотрена проектом.\nНа поверхностные марки (реперы), установленные на дамбах отстойника, должна быть составлена исполнительная документация, содержащая сведения о координатах и отметках. \nКаждый репер должен иметь маркировку и номер. Для предотвращения повреждения КИА автотранспортом, реперы оборудуются оголовками с сигнальными флажками (вешками).\nОтметка поверхностных марок (реперов на сооружениях) определяется от опорных реперов. Класс нивелирования, количество и место расположения опорных реперов, их поверка, применяемые приборы и требования к точности измерений обосновываются в программе геодезических наблюдений. \nПеред наступлением паводкового периода проводится комиссионное обследование ГТС.\nКонтроль системы КИА\nВизуально контролируется техническое состояние КИА, установленной для наблюдений за отстойниками: оголовков КИА, деформации конструкций КИА, наличие покраски, нумерации и т.п.\nПроверка опорного репера по координатам и отметкам должна производиться от государственной геодезической сети не реже одного раза в 3 года. В процессе измерений горизонтальных (плановых) перемещений следует контролировать устойчивость пунктов опорной сети для каждого цикла наблюдений. \nОтметки рабочих реперов (поверхностных марок на сооружениях) следует проверять от опорных реперов ежегодно.\nПлановое и высотное положение КИА контролируется не реже 1 раза в год. Поверка нуля водомерной рейки относительно опорного репера должна выполняться ежегодно.\nОграждающие дамбы отсеков «Северный», «Южный» «Восточный и их основания\nВ соответствии с СП 39.13330.2012 для оценки эксплуатационного состояния гидротехнических сооружений IV класса и их оснований необходимо предусматривать комплексные визуальные и инструментальные наблюдения.\nКонтроль состояния да отсеков отстойника включает:\nвизуальные наблюдения;\nгеодезический контроль;\nнаблюдения за температурным режимом.\nВизуальные наблюдения\nПри визуальных наблюдениях за состоянием отсеков отстойника должны контролироваться:\nсостояние откосов, наличие деформаций (осадки, смещения, просадки, оползни); \nвыявление мест выхода фильтрации, суффозии, оплывов, обрушений, деформаций и т.д.;\nсостояние доступных для осмотра частей КИА: наличие крышек, погнутых оголовков, нумерации и т. д.\nВизуальные наблюдения за состоянием ограждающих дамб выполняются ежедневно. Результаты наблюдений отражаются в «Журнале визуальных наблюдений».\nГеодезический контроль\nГеодезический контроль отстойника включает (2 раза в год):\nопределение крутизны откосов;\nопределение вертикальных и горизонтальных смещений бровки береговых склонов отстойника; тела и основания;\nизмерение геометрических размеров отстойника (длина, ширина, глубина).\nГеодезические и гидрографические наблюдения ведутся согласно СП 11.104-97.\nГлубина отсеков отстойника определяется при помощи промеров глубин эхолотами или намёткой, ручным или механическим лотом 2 раза в год. Измерения должны проводится с точностью не менее 0,1 м.\nРезультатом геодезического контроля является составление отчёта и оформление топоплана, а также анализ положения и крутизны бровок откосов, глубины отсеков отстойника в сравнении с топопланом предыдущих наблюдений.\nВсе геодезические и гидрографические наблюдения следует вести в одной системе координат - г. Норильска и Балтийской системе высот. \nПроектные параметры отстойника приведены в графической части проекта эксплуатации.\nВ случае, когда инструментальными наблюдениями выявлены возрастающие или незатухающие во времени деформации отдельных участков откосов, необходимо обращаться к представителям проектной организации для выявления причин и разработки мероприятий, обеспечивающих безаварийную работу сооружений.\nНаблюдения за температурным режимом \nНаблюдения осуществляются с целью обеспечения прочности и устойчивости откосов и основания отстойника с учётом развивающихся процессов оттаивания и криогенных явлений в откосах и основании.\nВ состав температурных наблюдений в настоящее время входят визуальное выявление за ходом развития мерзлотных процессов на откосах отстойника (гидролокаллиты, термокарсты, морозобойные трещины, наледи и т.д.).\nНеобходимость в наблюдениях за формированием температурного режима в основаниях и береговых примыканиях отстойника при помощи термометрических скважин определяется на основании анализа деформаций при геодезическом контроле и визуальных наблюдений за отстойником. Для принятия решения о необходимости, количестве и виде установки КИА, предназначенной для наблюдения за температурным режимом основания отстойника, следует привлекать проектные организации, имеющие соответствующий опыт.\nКонтроль состояния ёмкости отсеков отстойников\nОтстойник равнинного типа, оконтуренный по всему периметру ограждающей дамбой, поэтому поступление поверхностного стока и, соответственно, паводки в отстойнике отсутствуют. При осадках 1 % обеспеченности подъем уровня воды в пруду отстойника составит 5,0 мм, что при проектном превышении гребня дамбы над уровнем воды в пруду 1,0 м не вызовет перелива через гребень ограждающей дамбы.\nДля обеспечения водного баланса и бесперебойной работы системы оборотного водоснабжения необходимо исключить возможность переполнения отсеков отстойника и возникновения чрезвычайной ситуации. \nНаблюдения за заполнением отсеков отстойника включают:\nконтроль уровня и объёмов воды в отсеке;\nконтроль равномерного заполнения ёмкости отсека и объёмов налитых концентратов;\nконтроль объёмов поступающей воды (с пульпой) и забираемой в систему оборотного водоснабжения.\nКонтроль уровней воды прудка–отстойника выполняется по водомерной рейке с занесением в «Журнал наблюдений за уровнем воды в прудке-отстойнике».\nВизуальные наблюдения за режимом наполнения отсеков осуществляет персонал ЦГТС и ГТ с помощью мерной рейки с точностью до 1,0 см, не реже одного раза в смену.\nВ период весеннего паводка и дождевых осадков частоту наблюдений за подъёмом уровня воды в хвостохранилище увеличивают до двух раз в сутки в 8 часов утра и вечером 20 часов, результаты наблюдений заносят в журнал наблюдений.\nНа этот период вводят круглосуточное дежурство руководителей и специалистов, занятых на эксплуатации отстойника.\nКонтроль количества уложенного концентрата и объёма воды производится путём промеров глубин в отстойниках с точностью отсчёта отметок до 0,1 м.\nНе допускается несанкционированная и неорганизованная укладка концентрата. Запрещается сброс в отсеки отстойника продуктов, не предусмотренных проектом.\nПроводятся измерения расходов подаваемой в отстойник пульпы и оборотной воды, забираемой на завод, для контроля степени заполнения отстойника.\nДля отстойника устанавливаются следующие диагностические количественные показатели: отметка поверхности концентрата; глубина воды в отстойнике.\nВышеперечисленные количественные показатели контролируются инструментальными наблюдениями с помощью КИА или вычисляются на основе этих измерений.\nКонтроль технического состояния гидротехнических сооружений\nТехническое состояние комплекса ГТС устанавливается по результатам совокупности постоянных (непрерывных) наблюдений, включающие в себя:\nежеквартальные обследования технического состояния ГТС;\nкомиссионные предпаводковые обследования;\nвнеплановые комиссионные обследования.\nСостав и объём выполняемых визуальных и инструментальных наблюдений установлены в соответствии с Проектом мониторинга безопасности ГТС, 2023 г.\nНаиболее значимыми для безопасности состояния ГТС являются количественные и качественные диагностические показатели. На основании сравнения значений контролируемых показателей с критериями безопасности и допустимыми показателями контролируемых параметров основных сооружений и технологических объектов делается вывод об эксплуатационном состоянии ГТС.\nНа основе данных натурных наблюдений и геотехнического контроля, комиссионных обследований и осмотров сооружений, материалов проверок органами государственного надзора и экспертных заключений составляется годовой отчёт о состоянии ГТС, в котором делаются выводы о состоянии ГТС, его сооружении и систем, об уровне эксплуатации и безопасности, приводится перечень недостатков, подлежащих устранению, с указанием сроков.\nВ случае наступления эксплуатационного состояния ГТС, диагностируемого как удовлетворительное (частично неработоспособное), при превышении (уменьшении) значений одного или нескольких показателей критериев безопасности 1-го уровня (К1) следует проверить достоверность результатов измерений и вычислений, а также обоснованность принятых критериев безопасности. Собственник или эксплуатирующая организация обязаны предупредить об этом органы Ростехнадзора и принять оперативные меры по приведению ГТС в работоспособное состояние. При необходимости должна быть создана экспертная комиссия с привлечением проектной и экспертной организаций для уточнения оценки состояния сооружения и уровня его безопасности.\nПревышение значений одного или нескольких значений контролируемых показателей соответствующих критериев безопасности 2-го уровня следует считать признаком перехода сооружения в предаварийное (предельное) состояние, при котором дальнейшая эксплуатация ГТС в проектном режиме является нарушением Федерального закона «О безопасности гидротехнических сооружений» с вытекающей отсюда ответственностью. Все мероприятия по восстановлению надёжного состояния и ограничению режима эксплуатации сооружений должны осуществляться под непосредственным контролем органов Ростехнадзора с привлечением экспертных организаций. \nНа основе фактических физико-механических характеристик материалов сооружений и их оснований при необходимости (наличии признаков предаварийного состояния) комплексному анализу состояния сооружения подвергаются во внеочередном порядке.\nВ настоящее время при оценке технического состояния также допускается использование ГОСТ 31937-2011 «Здания и сооружения. Правила обследования и мониторинга технического состояния».\nОдними из ключевых документов, на основании которых делается вывод о техническом состоянии конструкций сооружения, являются Заключения по оценке технического состояния ГТС, выполненные специализированными организациями.\nТехническое состояние сооружений и систем отражается в технической документации организации, ответственной за проведение мониторинга сооружений (ЦНГТС ЗФ ПАО «ГМК «Норильский никель»).\nТехника безопасности при эксплуатации и ремонте сооружений и оборудования\nОсвещение (рабочее, аварийное, охранное и дежурное) всех объектов никелевого отстойника должно соответствовать СП 52.13330.2018.\nАвтомобильные служебные проезды вдоль откосов отстойника согласно СП 37.13330.2012 относятся к категории дороги III-в со скоростью движения не более 20 км/час.\nПроектные решения и само строительство автомобильных служебных проездов должны соответствовать СП 37.13330.2012.\nНа основании визуальных наблюдений и топогеодезических съёмок береговых склонов отстойника возможна установка на служебных автомобильных проездах информационных знаков типа: «Опасная зона отстойника. Возможно обрушение откоса».\nДля обеспечения безопасной эксплуатации отстойника запрещается:\nприсутствие на территории отстойника посторонних лиц;\nхождение по льду;\nиспользование воды из отстойника для хозяйственно-бутовых нужд;\nпередвижение по территории отстойника в одиночку при температурах наружного воздуха ниже минус 30 ºС, в туман или пургу;\nвыполнение строительно-монтажных работ подрядными организациями без наряда-допуска или акта-допуска;\nкупание.\nВсе движущиеся части агрегатов, оголённые части электрических устройств, зумпфы, пешеходные мостики, подмости должны иметь ограждения или перила высотой не менее 1,0 м.\nВсе служебные и бытовые помещения следует оборудовать автоматической пожарной сигнализацией с дежурным по ЦГТС и ГТ НОФ.\nВсе трубопроводы должны быть заземлены.\nПротивопожарные мероприятия\nПри возгорании кабеля или электрической насосной установки необходимо прекратить подачу напряжения на аварийный участок.\nДля тушения используются только порошковые или углекислотные огнетушители. Также наряду с огнетушителями используется сухой просеянный песок, который должен быть в наличии у пожарного щита, совместно с дополнительными приспособлениями противопожарной безопасности. Тушить песком целесообразно только на начальной стадии в сетях 0,4 кВ. \nМолниезащита сооружений\nКонструктивные элементы сооружений и оборудования никелевого отстойника имеют естественные внешние молниеприёмники и элементы токоотвода, для которых в соответствии с СО 153-34.21.122-2003 уровень защиты от прямого удара молнии (ПУМ) принят равным IV и дополнительных конструктивных молниезащитных элементов не требуется.\nВлияние отстойников на окружающую среду\nКонтроль влияния никелевого отстойника на окружающую среду должен осуществляться на основании «Программы мониторинга состояния и загрязнения окружающей среды на территории Никелевого отстойника НОФ в пределах его воздействия на окружающую среду». Результаты мониторинга отображают в отчётных данных.\nМониторинг безопасного состояния и загрязнения окружающей среды (ОС) на территории отстойника и в пределах его воздействия на ОС осуществляется в целях:\nсоблюдения требований природоохранного законодательства;\nпредотвращения, уменьшения и ликвидации (уменьшения) негативных изменений качества ОС.\nДля достижения указанных целей решаются следующие задачи:\nнаблюдение за состоянием внутренних и внешних откосов отсеков отстойника;\nоценка фильтрационного состояния отсеков отстойника.\nТерриториально никелевый отстойник расположен на территории Норильского промышленного района к югу от жилой зоны Центрального района МО г. Норильск.\nДля отстойника предусмотрена санитарно-защитная зона шириной 100 м.\nДля трубопроводов, оборудования, конструкций и сооружений, непосредственно входящих в состав трубопроводов или предназначенных для их эксплуатации, устанавливаются следующие охранные зоны по обе стороны трубопроводов:\nдля трубопроводов с условным диаметром до 1000 мм включительно - по 10 м в каждую сторону;\nдля трубопроводов с большим диаметром - по 20 метров в каждую сторону.\n Отсчёт расстояний при определении охранных зон трубопроводов производится от оси трубопровода - для одиночных трубопроводов и от осей крайних трубопроводов - для многониточных.\nНа никелевом отстойнике предусмотрен:\nконтроль химического состава поверхностных вод посредством забора проб и проведения лабораторных исследований, выполняемых 2 раза в год. Заборы производятся в районе водозабора насосной станции и из ручья Медвежий. \nДля проведения анализа воды нижнего бьефа отстойника, пробу воды отбирают из ручья Медвежий. Качество воды в нижнем бьефе должно соответствовать ПДК, установленными СанПиН 2.1.3684-21. Результаты замеров и проб воды заносятся в «Журнал учёта общего химического анализа воды».\nконтроль за состоянием прилегающей к ограждающим дамбам территории по степени заболачиваемости.\nМониторинг поверхностных вод в зоне влияния отстойника предусмотрен не только с целью оценки влияния фильтрации на окружающую среду, но и с целью предотвращения при эксплуатации опасных явлений, связанных появлением фильтрации и зон растепления.\nДля обеспечения устойчивой и надёжной эксплуатации всех сооружений отстойника и исключения аварий, которые могли бы привести к загрязнению окружающей среды, необходимо вести постоянный контроль и наблюдения за режимом их работы, соблюдать технологию летнего и зимнего складирования, проводить планово-предупредительные ремонты сооружений и оборудования в установленные сроки.\nВЕДЕНИЕ НАБЛЮДЕНИЙ И КОНТРОЛЬ ЗА БЕЗОПАСНОСТЬЮ ГТС\nВ соответствии с требованиями СП 58.13330.2019 для напорных гидротехнических сооружений III и IV классов ответственности применение автоматизированной системы диагностического контроля (АСДК) не требуется.\nНаблюдения за уровенным режимом прудов отстойников и контролем за деформациями ограждающей дамбы\nОборудование для ведения мониторинга \nДля контроля уровней воды в отстойниках «Северный», «Южный» и «Восточный» предусмотрена установка на откосах отстойников водомерной рейки (по одной для каждого отстойника).\nНа ограждающей дамбе отстойников предусмотрены наблюдательные посты (репера) в количестве 5 штук для геодезического контроля за деформациями ограждающей дамбы.\nНаблюдение за состоянием КИА заключается в следующем:\nпроверка опорного репера по координатам и отметкам должна проводиться от государственной геодезической сети не реже одного раза в три года. Отметки рабочих реперов следует проверять от опорных реперов ежегодно;\nметаллические части КИА должны быть защищены от коррозии, а на выступающие над поверхностью земли защитные колпаки (трубы) яркими несмывающимися красками должна быть нанесена нумерация.\nМесто расположения \nВодомерные рейки устанавливаются на внутреннем откосе прудов отстойников. Реперы на гребне ограждающей дамбы. \nМесто расположения измерительных приборов приведено в графических приложениях на листе 1006.3-ПрЭ л. 6.\nВедение контроля\nКонтроль и наблюдения за состоянием сооружений комплекса никелевого отстойника должен вестись в соответствии с «Проектом мониторинга безопасности ГТС никелевого отстойника» и в соответствии с «Правилами безопасности гидротехнических сооружений накопителей жидких промышленных отходов» (ПБ-03-438-02, используется справочно).\nКонтроль состояния ГТС Никелевого отстойника (отсеки «Северный», «Южный», «Восточный») осуществляется работниками ЦГТС и ГТ НОФ с привлечением специализированных служб ООО «Медвежий ручей», ЗФ ПАО «ГМК «Норильский никель» и сторонних организаций. Персоналом ЦГТС и ГТ обеспечивается ведение контроля и наблюдения за ГТС. Полученные данные заносятся в специальные журналы.\nДля обеспечения устойчивой и надёжной эксплуатации всех сооружений необходимо вести постоянный контроль и наблюдения за режимом их работы, проводить планово-предупредительные ремонты сооружений и оборудования в установленные сроки.\n Контроль и наблюдения должен вестись по следующим направлениям:\nТехнологические процессы.\nСостояние гидротехнических сооружений.\nВлияние на окружающую среду.\nСостояние проектной и эксплуатационной документации.\nПорядок подготовки и обучения эксплуатационного персонала.\nЭксплуатация никелевых отстойников включает в себя следующие технологические процессы: \nразработка земснарядом металлосодержащих продуктов и их гидротранспорт;\nгидротранспорт металлосодержащих материалов;\nосветление и оборот технической воды.\nОсновными количественными контролируемыми параметрами систем гидротранспорта являются: расход и консистенция пульпы; гранулометрический состав и плотность твёрдых частиц. Отбор проб пульпы производится из зумпфов, ежедневно. \nВсе параметры заносятся в соответствующие журналы «Журнал контроля характеристик пульпы» и «Журнал наблюдений за расходами пульпы».\nОсновными количественными параметром осветления воды в пруде является химический состав и мутность воды, а также глубина воды у водозабора. Пробы осветлённой воды берутся у сифонного водозабора, 1 раз в месяц.\nКонтроль состояния ограждающей дамбы и её основания включает:\nВизуальные наблюдения.\nГеодезический контроль.\nНаличие просадок, трещин, оползней, суффозионных явлений, появление сосредоточенных очагов фильтрации, наличие пучения и выпора грунтов за низовым откосом, а также контроль наличия и исправности КИА (визуальные наблюдения) проводятся регулярно, не реже 1 раза в неделю. Результаты визуальных наблюдений заносятся в «Журнал визуальных наблюдений».\nГеодезический контроль дамбы и её основания включает: геодезическое измерение планового и высотного положения КИА, а также измерения геометрических размеров дамбы. Измерения проводятся со следующей периодичностью: \nопределение вертикальных осадок тела дамбы – 1 раз в квартал;\nнивелирование реперов, а также контрольные промеры геометрических параметров – 1 раз в год;\nпривязка опорного репера по координатам и отметкам к государственной геодезической сети и измерение высотного положения КИА – 1 раз в 3 года.\nВсе полученные результаты заносятся в соответствующие журналы.\nКонтроль и наблюдения состояния ёмкости отсеков никелевого отстойника включают:\nконтроль измерения уровня воды по водомерной рейке, ежедневно;\nконтроль заполнения отсеков никелевого отстойника путём промеров глубин с помощью специального лота.\nКонтроль работы трубопроводов заключается в определении толщины стенки трубы (2 раза в год), а также в визуальном наблюдении состояния трубопроводов (отсутствие течей, просадок опор и т.д.).\nКонтроль и наблюдения насосных установок (как в насосной станции, так и на земснарядах) включают в себя как визуальные наблюдения (состояние, собственно, насосного оборудования, а также исправность запорной арматуры), проводимые ежесменно, так и инструментальные: измерение производительности насосов; давления (манометры на всасе и напоре), фактической мощности.\nНа участке гидромеханизации, ведущим эксплуатацию никелевого отстойника, должны быть следующие документы:\nПлан ликвидации аварий на гидротехнических сооружениях.\nМестная инструкция по эксплуатации.\nПаспорта гидротехнических сооружений (ежегодно корректируемые).\nСхема сооружений комплекса никелевого отстойника.\nХиманализы воды: у сифонного водозабора.\nПроект эксплуатации никелевого отстойника на текущий период.\nПроект мониторинга безопасности ГТС никелевого отстойника.\nПлан подготовки к весеннему снеготаянию.\nТопографические съёмки никелевого отстойника.\n\tАкты на скрытые работы. \nЖурналы наблюдений.\nГодовые отчёты о состоянии отсеков никелевого отстойника.\nКонтролируемые параметры и критерии безопасности\nПеречень контролируемых параметров и критерии безопасности содержатся в проекте мониторинга шифр 07-04-231. \nКБ разработаны для удобства ведения наблюдений за ГТС и оценки их технического состояния.\nКритерии безопасности 1-го уровня – значения контролируемых показателей состояния ГТС, определяемые при основном сочетании нагрузок, при достижении которых устойчивость, механическая и фильтрационная прочность ГТС соответствуют условиям их нормальной эксплуатации.\nКритерии безопасности 2-го уровня – значения контролируемых показателей состояния ГТС, устанавливаемые при особом сочетании нагрузок, при превышении (уменьшении) которых эксплуатация ГТС в проектном режиме не допустима, состояние контролируемого сооружения может перейти в предаварийное состояние. Все мероприятия по восстановлению надёжного состояния и ограничению режима эксплуатации сооружений должны осуществляться под непосредственным контролем органов Ростехнадзора с привлечением экспертных организаций. \n При наступлении К2 на водоводах или пульповодах следует отключить участок трубопровода и использовать резервный. \nТаблица 4.1 – Количественные диагностические показатели состояния ГТС никелевого отстойника и их критериальные значения\n№ п/п\n\u0007Наименование показателя\n\u0007Критериальные значения показателей\n\u0007\n\u0007\n\u0007\n\u0007К1\n\u0007К2\n\u0007\n\u0007Ограждающая дамба\n\u0007\n\u00071.1\n\u0007Превышение отметки гребня дамбы над уровнем воды, м\n\u0007не менее 1,0\n\u0007не менее 0,6\n\u0007\n\u00071.2\n\u0007Геометрические параметры ограждающей дамбы:\n- минимальная ширина гребня, м\n- крутизна низового откоса\n\u0007\n\nне менее 8,0\nне менее 1: 1,5\n\u0007\n\nне менее 4,5\nне менее 1: 1,2\n\u0007\n\u0007Таблица 4.2 – Качественные диагностические показатели состояния ГТС никелевого отстойника и их критериальные значения\n№ п/п\n\u0007Наименование показателя\n\u0007Критериальные значения показателей\n\u0007\n\u0007\n\u0007\n\u0007К1\n\u0007К2\n\u0007\n\u0007Ограждающая дамба\n\u0007\n\u00071.1\n\u0007Состояние откосов и гребня дамбы\n\u0007Наличие продольных трещин на гребне и откосах без признаков локального оползания и оплывания откосов\n\u0007Развитие во времени продольных трещин, увеличение ширины их раскрытия, локальное оползание и оплывание откосов\n\u0007\n\u00071.2\n\u0007Состояние мест выхода фильтрационного потока (низовой откос и основание у подошвы низового откоса)\n\u0007Стабильное состояние наблюдаемых мест высачивания профильтровавшейся воды и наледей без изменения во времени их геометрических параметров\n\u0007Увеличение во времени расходов в местах выхода фильтрационных вод фиксируемых визуально\n\u0007\n\u00071.3\n\u0007Контур дамбы и её конструктивные элементы\n\u0007Появление просадок, локального оползания грунта на откосах и гребне, появление продольных и поперечных трещин, выпора грунта на откосах и у подошвы дамбы\n\u0007Появление воронок и оползневых «цирков», способных привести к обрушению, оползанию и переформированию откоса\n\u0007\n\u0007Подводящие и отводящие трубопроводы\n\u0007\n\u00072.1\n\u0007Состояние металла трубопроводов\n\u0007Продольные цепочки не сквозной язвенной коррозии, наличие не сквозных трещин всех видов и направлений, механических повреждений, не влияющих на герметичность трубопровода\n\u0007Увеличение трещин и коррозионных повреждений, приводящие к образованию протечек. Уменьшение пропускной способности трубопровода, при-водящее к невозможности его эксплуатации в проектном режиме\n\u0007\n\u00072.2\n\u0007Состояние территории около трубопровода\n\u0007Наличие ограничений подъезда (завал грунтами, мусором, снегом) к участкам трассы трубопровода для обслуживающей спецтехники и механизмов\n\u0007Состояние территории не позволяет выполнять ремонтные работы. \nОтсутствие возможности проехать к ГТС на вездеходной технике\n\u0007\n\u00072.3\n\u0007Состояние трассы и материала трубопроводов\n\u0007Нарушенная антикоррозийная и теплоизоляция трубопроводов до 10 %, герметичность стыков, швов, фланцевых соединений, отсутствие протечек.\nНезначительные осадки и деформации трубопроводов, просадки грунта по трассе трубопроводов и вблизи от неё, не приводящие к разрыву трубопровода Трубопроводная арматура в рабочем состоянии; отсутствие разрывов в трубопроводах\n\u0007Нарушенная изоляция трубопроводов более 50 %, наличие свищей, наличие деформации трубопроводов с провисанием, протечки\n\u0007\n\u0007Сифонный водозабор\n\u0007\n\u00073.1\n\u0007Состояние сифонного водозабора\n\u0007Механические повреждения труб (просадки, крен, вмятины), не приводящее к нарушению его пропускной способности\n\u0007Механические повреждения труб (просадки, крен, вмятины), приводящие к нарушению его пропускной способности\n\u0007\n\u0007Береговая насосная станция\n\u0007\n\u00074.1\n\u0007Береговая насосная станция\n\u0007Оптимальный режим работы насосного оборудования, отсутствие кавитационных режимов работы, протечек корпуса, не характерных шумов\n\u0007Работа в режиме кавитации, разрыв водоводов\n\u0007\n\u0007\nПЕРЕЧЕНЬ ПЕРСОНАЛА, ОБОРУДОВАНИЯ И МЕХАНИЗМОВ, НЕОБХОДИМЫХ ПРИ ЭКСПЛУАТАЦИИ ОТСТОЙНИКА НИКЕЛЕВОГО КОНЦЕНТРАТА НОРИЛЬСКОЙ ОБОГАТИТЕЛЬНОЙ ФАБРИКИ\nДля механизации трудоёмких и ручных работ служба эксплуатации отстойников должна иметь ряд машин и механизмов, количество и состав которых зависят от конструктивных особенностей отстойников, систем гидротранспорта и оборотного водоснабжения, объёма ежегодно выполняемых работ. Примерный перечень рекомендуемых машин и механизмов при эксплуатации приведён в СТО СРО-П 60542948 00054-2018.\nТаблица 5.1 – Перечень оборудования, машин и механизмов при эксплуатации отстойников никелевого концентрата НОФ\nНаименование машин и механизмов\n\u0007Выполняемые работы\n\u0007\n\u0007Экскаватор универсальный со сменным оборудованием\n\u0007Отсыпка технологических проездов и площадок, планировка и очистка откосов отстойников, монтаж и демонтаж распределительных пульпопроводов, перемещение плавучих насосных станций\n\u0007\n\u0007Автомобильный кран\n\u0007Монтаж и демонтаж магистральных пульпопроводов и водоводов, другие погрузочно-разгрузочные работы\n\u0007\n\u0007Трубоукладчик \n\u0007Монтаж, демонтаж и ремонтные работы на пульпопроводах и водоводах \n\u0007\n\u0007Бульдозер\n\u0007Отсыпка технологических проездов и площадок, перемещение грузов \n\u0007\n\u0007Автомобиль грузовой\n\u0007Перевозка различных грузов\n\u0007\n\u0007Мастерская ремонтная передвижная\n\u0007Ремонт машин и механизмов\n\u0007\n\u0007Передвижной сварочный аппарат\n\u0007Сварочные работы на пульпопроводах и водоводах \n\u0007\n\u0007Передвижная компрессорная станция\n\u0007Ремонтные работы\n\u0007\n\u0007Передвижной самовсасывающий насос\n\u0007Откачка воды из траншей, котлованов и отстойников, возврат хвостовой воды в отстойники \n\u0007\n\u0007Потокообразователь\n\u0007Образование майны около плавучей насосной станции или земснаряда \n\u0007\n\u0007Поливомоечная машина\n\u0007Увлажнение технологических проездов и площадок\n\u0007\n\u0007Лодка \n\u0007Для перемещения людей по отстойнику\n\u0007\n\u0007Автомобиль внедорожный\n\u0007Транспорт для осмотра сооружений отстойников\n\u0007\n\u0007Плавающий земснаряд Shark SH-4250-60-30D№1\n\u0007Откачка металлосодержащего продукта через зумпф в насосную станцию никелевого концентрата\n\u0007\n\u0007Земснаряд «Ахтарец» 400/40, дизельный с фрезерным рыхлителем\n\u0007Перекачка осветлённой воды из пруда в Северный отсек DN400, а также откачка металлосодержащего продукта DN273 через зумпф в насосную станцию\n\u0007\n\u0007Гидромонитор «Watermaster Classic IV\n\u0007Откачка металлосодержащего продукта DN273 через зумпф в насосную станцию, а при необходимости в Южный отсек DN273\n\u0007\n\u0007Зумпф (2 шт.)\n\u0007Отсев крупной фракции при разработке отстойников и перекачке никелевого концентрата\n\u0007\n\u0007Приведённый в таблице Таблица 5.1 состав машин и механизмов может быть изменён в зависимости от конкретных условий.\nПри выборе машин и механизмов для службы эксплуатации отстойников следует отдавать предпочтение более производительным типам, отвечающим современному уровню развития техники.\nЭксплуатация ГТС Никелевого отстойника НОФ осуществляется работниками ООО «Медвежий ручей», непосредственно – структурным подразделением ЦГТС и ГТ НОФ. \nСостав рабочих и ИТР определён штатным расписанием. Штатное расписание эксплуатационного персонала участков ЦГТС и ГТ приведено в таблице Таблица 5.2.\nТаблица 5.2 – Штатное расписание эксплуатационного персонала объекта\n№ п/п\n\u0007Должность (профессия)\n\u0007Квалификационный разряд (образование)\n\u0007Количество штатных единиц/\u000bФактическая численность\n\u0007\n\u00071\n\u00072\n\u00073\n\u00074\n\u0007\n\u0007Участок складирования хвостов и металлосодержащих материалов\n\u0007\n\u00071\n\u0007Начальник участка\n\u0007Высшее или среднее профессиональное (техническое)\n\u00071/1\n\u0007\n\u00072\n\u0007Старший мастер по ремонту оборудования\n\u0007Высшее или среднее профессиональное (техническое)\n\u00071/-\n\u0007\n\u00073\n\u0007Мастер по ремонту оборудования\n\u0007Высшее или среднее профессиональное (техническое)\n\u00073/3\n\u0007\n\u00074\n\u0007Мастер производственного участка\n\u0007Высшее или среднее профессиональное (техническое)\n\u00073/3\n\u0007\n\u0007Бригада по обслуживанию и ремонту намывных и магистральных пульпопроводов\n\u0007\n\u00075\n\u0007Машинист трубоукладчика\n\u00076 разряд\n\u00072/-\n\u0007\n\u00076\n\u0007Слесарь-ремонтник\n\u00075 разряд\n\u00077/7\n\u0007\n\u00077\n\u0007Слесарь-ремонтник\n\u00074 разряд\n\u00072/2\n\u0007\n\u00078\n\u0007Регулировщик хвостового хозяйства\n\u00074 разряд\n\u000723/22\n\u0007\n\u0007Бригада по обслуживанию и ремонту электрооборудования участка\n\u0007\n\u00079\n\u0007Электромонтёры по ремонту и обслуживанию электрооборудования\n\u00076 разряд\n\u00073/2\n\u0007\n\u0007\n\u0007\n\u00075 разряд\n\u00075/5\n\u0007\n\u0007\n\u0007\n\u00074 разряд\n\u00075/4\n\u0007\n\u0007Бригада по обслуживанию и ремонту технологического оборудования участка\n\u0007\n\u000710\n\u0007Слесарь-ремонтник\n\u00075 разряд\n\u000710/10\n\u0007\n\u000711\n\u0007Слесарь-ремонтник\n\u00074 разряд\n\u00079/9\n\u0007\n\u000712\n\u0007Слесарь-ремонтник\n\u00073 разряд\n\u00071/1\n\u0007\n\u000713\n\u0007Электрогазосварщик\n\u00075 разряд\n\u00073/3\n\u0007\n\u0007Бригада специализированная по обслуживанию оборудования насосных станций участка\n\u0007\n\u000714\n\u0007Машинист насосной установки\n\u00075 разряд\n\u00078/8\n\u0007\n\u000715\n\u0007Машинист насосной установки\n\u00074 разряд\n\u000712/11\n\u0007\n\u000716\n\u0007Машинист насосной установки\n\u00073 разряд\n\u00078/8\n\u0007\n\u0007Участок гидромеханизации\n\u0007\n\u000717\n\u0007Начальник участка\n\u0007Высшее или среднее профессиональное (техническое)\n\u00071/1\n\u0007\n\u000718\n\u0007Мастер производственного участка\n\u0007Высшее или среднее профессиональное (техническое)\n\u00071/1\n\u0007\n\u000719\n\u0007Машинист землесосного плавучего несамоходного снаряда\n\u00074 разряд\n\u00079/7\n\u0007\n\u0007\n\u0007\n\u00075 разряд\n\u000717/14\n\u0007\n\u0007Участок гидротранспорта\n\u0007\n\u000720\n\u0007Начальник участка\n\u0007Высшее или среднее профессиональное (техническое)\n\u00071/1\n\u0007\n\u000721\n\u0007Мастер производственного участка\n\u0007Высшее или среднее профессиональное (техническое)\n\u00071/1\n\u0007\n\u0007Бригада по ремонту и обслуживанию п/проводов низкого давления\n\u0007\n\u000722\n\u0007Слесарь-ремонтник\n\u00074 разряд\n\u00071/1\n\u0007\n\u000723\n\u0007Слесарь-ремонтник\n\u00075 разряд\n\u00072/2\n\u0007\n\u000724\n\u0007Электрогазосварщик\n\u00074 разряд\n\u00072/2\n\u0007\n\u000725\n\u0007Электрогазосварщик\n\u00075 разряд\n\u000710/10\n\u0007\n\u0007Итого:\n\u0007151/139\n\u0007\n\u0007Приведённый в таблице Таблица 5.2 состав обслуживающего персонала может быть изменён в зависимости от конкретных условий.\nСуществующая на объекте производственная структура и квалификация персонала соответствуют предъявляемым требованиям нормативных документов по эксплуатации и контролю состояния гидротехнических сооружений и их электромеханического оборудования.\nРабочие, обслуживающие ГТС, каждые 6 месяцев проходят повторный инструктаж по безопасности труда и 1 раз в год проверку знаний должностных инструкций.\nМЕРОПРИЯТИЯ ПО ПРЕДУПРЕЖДЕНИЮ ЧРЕЗВЫЧАЙНЫХ СИТУАЦИЙ\nПредупреждение чрезвычайных ситуаций - это комплекс мероприятий, проводимых заблаговременно и направленных на максимально возможное уменьшение риска возникновения чрезвычайных ситуаций, а также на сохранение здоровья людей, снижение размеров ущерба окружающей среде и материальных потерь в случае их возникновения.\nНа ГТС Никелевого отстойника (отсеки «Северный», «Южный», «Восточный») НОФ должен быть обеспечен постоянный контроль за состоянием безопасности гидротехнических сооружений и их воздействием на окружающую среду, предотвращением возникновения аварийных ситуаций и созданием условий для безопасной эксплуатации.\nВ соответствии с Федеральным законом «О безопасности гидротехнических сооружений» от 21.07.1997 № 117-ФЗ (глава II, статья 9), собственник гидротехнического сооружения и (или) эксплуатирующая организация обязаны обеспечивать контроль (мониторинг) за показателями состояния гидротехнического сооружения, природных и техногенных воздействий и на основании полученных данных осуществлять регулярную оценку безопасности гидротехнического сооружения и анализ причин её снижения с учётом вредных природных и техногенных воздействий, результатов хозяйственной и иной деятельности, в том числе деятельности, связанной со строительством и с эксплуатацией объектов на водных объектах и на прилегающих к ним территориях.\nВ соответствии с Федеральным законом от 21 декабря 1994 г. № 68-ФЗ «О защите населения и территорий от чрезвычайных ситуаций природного и техногенного характера», утверждены требования по предупреждению чрезвычайных ситуаций на потенциально опасных объектах и объектах жизнеобеспечения.\nВо исполнение основных требований по предупреждению чрезвычайных ситуаций и согласно № 117-ФЗ на потенциально опасных ГТС Никелевого отстойника на предприятии должны быть:\nразработаны распорядительные и организационные документы по вопросам предупреждения чрезвычайных ситуаций;\nразработаны планы мероприятий по предупреждению чрезвычайных ситуаций характера, определение и периодическое уточнение показателей степени риска чрезвычайных ситуаций техногенного характера для производственного персонала и населения на прилегающей территории при декларировании ГТС;\nобеспечена готовность объектовых органов управления, сил и средств к действиям по предупреждению и ликвидации чрезвычайных ситуаций;\nпроводится подготовка персонала к действиям при чрезвычайных ситуациях;\nдекларирование безопасности ГТС ведётся согласно утверждённого графика Ростехнадзора;\nежегодно проводится страхование гражданской ответственности за причинение вреда при эксплуатации гидротехнического сооружения;\nдля предоставления информации о потенциально опасном объекте по запросам граждан и общественных организаций используется «Информационный лист» организации установленной формы;\nсозданы объектовые резервы материальных и финансовых ресурсов для ликвидации чрезвычайных ситуаций.\nБезаварийная эксплуатация ГТС Никелевого отстойника (отсеки «Северный», «Южный», «Восточный») должна обеспечиваться выполнением следующих условий:\nЭксплуатация ГТС в соответствии с требованиями «Местной инструкцией по эксплуатации ГТС» и «Правилами эксплуатации ГТС Никелевого отстойника (отсеки «Северный», «Южный», «Восточный») НОФ.\nПрофессиональная подготовка и своевременное повышение квалификации персонала, обслуживающего ГТС Никелевого отстойника.\nВедение постоянного контроля состояния сооружений в соответствии с «Проектом мониторинга ГТС Никелевого отстойника (отсеки «Северный», «Южный», «Восточный») НОФ, обеспечивающего должный уровень безопасности ГТС и соблюдение требований по основным диагностируемым параметрам.\nКонтроль состояния ГТС Никелевого отстойника (отсеки «Северный», «Южный», «Восточный») осуществляется работниками ЦГТС и ГТ НОФ с привлечением специализированных служб ООО «Медвежий ручей», ЗФ ПАО «ГМК «Норильский никель» и сторонних организаций. Персоналом ЦГТС и ГТ обеспечивается ведение контроля и наблюдения за ГТС. Полученные данные заносятся в специальные журналы.\nС целью обеспечения безаварийной работы ГТС и соблюдения правил их эксплуатации два раза в год – перед наступлением тёплого и зимнего сезонов – проводится комиссионное обследование сооружений хвостохранилища. По результатам обследований главный инженер ООО «Медвежий ручей» утверждает акт о готовности гидротехнических сооружений хвостохранилища к приёму паводка и к работе в зимних условиях.\nЭксплуатационная надёжность и безопасность хвостохранилища подтверждается комиссионными обследованиями, выполняемыми ЦГТС и ГТ НОФ совместно с ГТЛ ЦНГТС. При необходимости комплексных обследований дополнительно привлекаются специализированные организации. \nПериодичность осмотра ГТС административно-техническим персоналом устанавливается утверждённым графиком по предприятию.\nСравнение значений критериев безопасности с действительными значениями показателей состояния сооружений в процессе эксплуатации даёт возможность оценить уровень безопасного состояния гидротехнических сооружений.\nТакже на объекте имеется «План ликвидации аварий ЦГТС и ГТ НОФ. Никелевый отстойник. 2023 год», утв. зам. Генерального директора ООО «Медвежий ручей» - заместителем генерального директора 15.12.2022 г. В ПЛА отражены все основные мероприятия и действия персонала при аварии.\nПлан ликвидации аварий ЦГТС и ГТ НОФ соответствует фактическому положению на отстойнике и обеспечивает безопасные условия работы технологического и другого персонала при спасении людей и ликвидации (локализации) возможных аварий. В имеющемся ПЛА чётко расписаны оперативные действия эксплуатационного персонала и рассмотрены наиболее характерные для данного объекта сценарии предаварийных (аварийных) ситуаций.\nВ ООО «Медвежий ручей» создана ЛСО (Распоряжение № ЗФ-71/07-р-а от 24.01.2014 «О вводе в промышленную эксплуатацию локальной системы оповещения ЛСО»), которая включает системы оповещения на каждом из объектов и центральный диспетчерский пункт, который сопрягается с АСЦО вышестоящего уровня. Запуск процесса системы ЛСО осуществляется диспетчером НОФ в соответствии с инструкцией (приложение к ПЛА). Предусмотрено сопряжение с автоматизированной системой централизованного оповещения города Норильск.\nМЕРОПРИЯТИЯ НА СЛУЧАЙ КОНСЕРВАЦИИ\nКонсервация или ликвидация ГТС Никелевого отстойника НОФ собственником и эксплуатирующей организацией в настоящем проекте не планируются.\nПри технологическом потоке на Никелевый отстойник предусмотрены следующие мероприятия по обеспечению безопасности ГТС:\nвсе водоперепускные устройства поддерживаются в работоспособном состоянии. Проверка и текущий ремонт сифонного водозабора, проверка работоспособности и текущий ремонт плавучих и береговых насосных станций, проверка и текущий ремонт трубопроводов насосных станций;\nосуществляется мониторинг безопасности ГТС, периодически проводятся комиссионные обследования ГТС;\nне реже одного раза в пять лет осуществляется регулярное обследование ГТС с участием надзорных органов и декларирование безопасности ГТС.", "[стр. 7]\nПриложение А\u000bТехническое задание\n/", "[стр. 8]\n/", "[стр. 9]\n/\n///////////////", "[стр. 10]\nГрафические приложения"]};
